```html
<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Plan Maestro OS · Segundo Cerebro Operativo</title>
<link rel="stylesheet" href="https://cdn.jsdelivr.net/fontsource/fonts/inter@latest/latin-400-normal.min.css">
<link rel="stylesheet" href="https://cdn.jsdelivr.net/fontsource/fonts/inter@latest/latin-500-normal.min.css">
<link rel="stylesheet" href="https://cdn.jsdelivr.net/fontsource/fonts/inter@latest/latin-600-normal.min.css">
<link rel="stylesheet" href="https://cdn.jsdelivr.net/fontsource/fonts/inter@latest/latin-700-normal.min.css">
<link rel="stylesheet" href="https://cdn.jsdelivr.net/fontsource/fonts/inter@latest/latin-800-normal.min.css">
<link rel="stylesheet" href="https://cdn.jsdelivr.net/fontsource/fonts/space-grotesk@latest/latin-700-normal.min.css">
<link rel="stylesheet" href="https://cdn.jsdelivr.net/fontsource/fonts/jetbrains-mono@latest/latin-600-normal.min.css">
<style>
/* ============ TOKENS · Impeccable: dark estructural, jerarquía tipográfica, sin ruido ============ */
:root{
  --bg:#000;
  --surface:rgba(28,28,30,.75);
  --surface-2:rgba(44,44,46,.72);
  --surface-3:rgba(58,58,60,.6);
  --pill-bg:rgba(0,0,0,.4);
  --border:rgba(255,255,255,.08);
  --border-2:rgba(255,255,255,.14);
  --text:#f5f5f7;
  --text-2:rgba(235,235,245,.62);
  --text-3:rgba(235,235,245,.38);
  --accent:#0a84ff;
  --done:#30d158;
  --warn:#ffd60a;
  --warn-2:#ff9f0a;
  --danger:#ff453a;
  --purple:#bf5af2;
  --r-lg:24px; --r-md:14px; --r-sm:10px;
  --blur:blur(40px) saturate(180%);
  --shadow:0 20px 50px rgba(0,0,0,.5), inset 0 1px 0 rgba(255,255,255,.08);
  --fs-title:clamp(1.5rem,3vw,1.9rem);
  --fs-h2:1.15rem;
  --fs-body:.95rem;
  --fs-label:.86rem;
  --fs-meta:.78rem;
}
*{margin:0;padding:0;box-sizing:border-box}
html{scroll-behavior:smooth}
body{
  background:var(--bg);color:var(--text);
  font-family:'Inter',system-ui,-apple-system,sans-serif;
  font-size:var(--fs-body);line-height:1.55;
  min-height:100vh;overflow-x:hidden;
}
body::before{content:'';position:fixed;inset:0;z-index:-1;
  background:
    radial-gradient(1100px 600px at 85% -10%, rgba(10,132,255,.14), transparent 60%),
    radial-gradient(900px 500px at -10% 30%, rgba(191,90,242,.08), transparent 60%),
    radial-gradient(700px 500px at 50% 110%, rgba(48,209,88,.06), transparent 60%),
    #000;
}
h1,h2,h3{font-family:'Space Grotesk','Inter',sans-serif;letter-spacing:-.02em}
button{font-family:inherit;color:inherit;background:none;border:none;cursor:pointer}
a{color:inherit;text-decoration:none}
:focus-visible{outline:2px solid var(--accent);outline-offset:2px;border-radius:6px}
.mono{font-family:'JetBrains Mono',monospace;font-variant-numeric:tabular-nums}
::selection{background:rgba(10,132,255,.4)}
@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}

/* ============ HEADER ============ */
header{
  position:sticky;top:0;z-index:50;
  background:var(--surface);backdrop-filter:var(--blur);-webkit-backdrop-filter:var(--blur);
  border-bottom:1px solid var(--border);
}
.header-in{max-width:1120px;margin:0 auto;padding:10px 20px;display:flex;align-items:center;gap:14px}
.brand{display:flex;align-items:center;gap:10px;font-weight:800;font-size:.98rem;letter-spacing:-.01em}
.brand-mark{width:30px;height:30px;border-radius:9px;background:linear-gradient(135deg,#0a84ff,#bf5af2);display:grid;place-items:center;box-shadow:0 4px 14px rgba(10,132,255,.35)}
.brand small{display:block;font-size:.66rem;font-weight:600;color:var(--text-3);letter-spacing:.12em;text-transform:uppercase}
.desktop-nav{margin-left:auto;display:none;gap:4px;background:var(--pill-bg);border:1px solid var(--border);border-radius:12px;padding:4px}
@media(min-width:768px){.desktop-nav{display:flex}}
.nav-item{display:inline-flex;align-items:center;gap:7px;padding:7px 15px;border-radius:8px;border:1px solid transparent;font-size:.84rem;font-weight:600;color:var(--text-2);transition:all .15s ease}
.nav-item:hover{color:var(--text);background:rgba(255,255,255,.06)}
.nav-item.active{background:rgba(255,255,255,.12);border-color:rgba(255,255,255,.2);color:var(--text)}
.energy-chip{display:inline-flex;align-items:center;gap:6px;font-size:.74rem;font-weight:700;padding:6px 11px;border-radius:999px;border:1px solid var(--border-2);background:var(--pill-bg);color:var(--text-2)}
.energy-chip .dot{width:8px;height:8px;border-radius:50%}

/* more popover */
.more-wrap{position:relative}
.more-pop{position:absolute;right:0;top:calc(100% + 8px);width:230px;background:rgba(30,30,32,.92);backdrop-filter:var(--blur);border:1px solid var(--border-2);border-radius:16px;padding:8px;box-shadow:var(--shadow);z-index:60;animation:pop .16s ease}
@keyframes pop{from{opacity:0;transform:translateY(-6px) scale(.98)}to{opacity:1;transform:none}}
.pop-label{font-size:.68rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--text-3);padding:6px 10px 4px}
.pop-item{display:flex;align-items:center;gap:10px;width:100%;padding:9px 10px;border-radius:10px;font-size:.88rem;font-weight:550;color:var(--text-2);transition:background .12s}
.pop-item:hover{background:rgba(255,255,255,.07);color:var(--text)}

/* ============ LAYOUT ============ */
main{max-width:1120px;margin:0 auto;padding:26px 20px 110px}
@media(min-width:768px){main{padding-bottom:60px}}
.page{display:flex;flex-direction:column;gap:20px;animation:fadein .28s ease}
@keyframes fadein{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
.crumb{font-size:var(--fs-meta);color:var(--text-3);font-weight:600}
.page h1{font-size:var(--fs-title);font-weight:700}
.card{background:var(--surface);backdrop-filter:var(--blur);-webkit-backdrop-filter:var(--blur);border:1px solid var(--border-2);border-radius:var(--r-lg);padding:22px;box-shadow:var(--shadow)}
.card h2{font-size:var(--fs-h2);font-weight:700;margin-bottom:4px}
.card .sub{color:var(--text-2);font-size:var(--fs-label)}
.section-label{font-size:var(--fs-meta);font-weight:700;text-transform:uppercase;letter-spacing:.09em;color:var(--text-3)}
.grid-2{display:grid;gap:16px;grid-template-columns:1fr}
@media(min-width:900px){.grid-2{grid-template-columns:1fr 1fr}}

/* pills tabs */
.pills{display:flex;gap:4px;background:var(--pill-bg);border:1px solid var(--border);border-radius:12px;padding:4px;width:fit-content;max-width:100%;overflow-x:auto}
.pill{padding:7px 16px;border-radius:8px;border:1px solid transparent;font-size:.82rem;font-weight:600;color:rgba(255,255,255,.45);white-space:nowrap;transition:all .15s ease}
.pill:hover{color:var(--text)}
.pill.active{background:rgba(255,255,255,.12);border-color:rgba(255,255,255,.2);color:var(--text);font-weight:700}

/* buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:9px 16px;border-radius:var(--r-md);font-size:.86rem;font-weight:650;border:1px solid var(--border-2);background:var(--surface-2);transition:all .15s ease;white-space:nowrap}
.btn:hover{background:var(--surface-3);transform:translateY(-1px)}
.btn:active{transform:translateY(0)}
.btn.primary{background:var(--accent);border-color:transparent;color:#fff;box-shadow:0 6px 18px rgba(10,132,255,.35)}
.btn.primary:hover{filter:brightness(1.1)}
.btn.success{background:rgba(48,209,88,.16);border-color:rgba(48,209,88,.4);color:var(--done)}
.btn.warn{background:rgba(255,159,10,.14);border-color:rgba(255,159,10,.4);color:var(--warn-2)}
.btn.ghost{background:transparent;border-color:transparent;color:var(--text-2)}
.btn.ghost:hover{background:rgba(255,255,255,.07);color:var(--text)}
.btn.sm{padding:6px 12px;font-size:.78rem;border-radius:10px}
.btn.icon{padding:6px 10px}
.btn:disabled{opacity:.4;cursor:not-allowed;transform:none}

/* badges & chips */
.badge{display:inline-flex;align-items:center;gap:5px;font-size:.68rem;font-weight:750;padding:3px 9px;border-radius:999px;letter-spacing:.03em}
.badge.blue{background:rgba(10,132,255,.16);color:#64b5ff;border:1px solid rgba(10,132,255,.35)}
.badge.green{background:rgba(48,209,88,.14);color:var(--done);border:1px solid rgba(48,209,88,.35)}
.badge.yellow{background:rgba(255,214,10,.12);color:var(--warn);border:1px solid rgba(255,214,10,.3)}
.badge.orange{background:rgba(255,159,10,.14);color:var(--warn-2);border:1px solid rgba(255,159,10,.35)}
.badge.red{background:rgba(255,69,58,.14);color:var(--danger);border:1px solid rgba(255,69,58,.35)}
.badge.purple{background:rgba(191,90,242,.14);color:var(--purple);border:1px solid rgba(191,90,242,.35)}
.badge.gray{background:rgba(255,255,255,.08);color:var(--text-2);border:1px solid var(--border-2)}

/* list rows */
.row{display:flex;align-items:center;gap:12px;width:100%;text-align:left;padding:12px 14px;border-radius:var(--r-md);border:1px solid var(--border);background:var(--surface-2);transition:all .14s ease}
.row:hover{border-color:var(--border-2);background:var(--surface-3)}
.row .t{font-weight:650;font-size:.9rem}
.row .m{font-size:var(--fs-meta);color:var(--text-3)}
.row .grow{flex:1;min-width:0}
.row.done .t{text-decoration:line-through;color:var(--text-3)}

/* program rail */
.rail{display:flex;gap:14px;overflow-x:auto;padding:4px 2px 14px;scroll-snap-type:x proximity}
.pcard{min-width:240px;max-width:260px;scroll-snap-align:start;background:var(--surface-2);border:1px solid var(--border-2);border-radius:18px;padding:16px;display:flex;flex-direction:column;gap:8px;cursor:pointer;transition:all .16s ease;position:relative}
.pcard:hover{transform:translateY(-3px);border-color:rgba(10,132,255,.45);box-shadow:0 10px 30px rgba(0,0,0,.45)}
.pcard.inspected{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent),0 10px 30px rgba(10,132,255,.2)}
.pcard .pt{font-weight:750;font-size:.95rem;letter-spacing:-.01em}
.pcard .ps{font-size:.72rem;color:var(--text-3);font-weight:600}
.pcard .pm{font-size:.74rem;color:var(--text-2)}
.pcard .abs{position:absolute;top:10px;right:10px;width:28px;height:28px;border-radius:9px;display:grid;place-items:center;font-weight:800;font-size:1rem;border:1px solid var(--border-2);background:var(--pill-bg);transition:all .14s}
.pcard .abs:hover{transform:scale(1.08)}
.pcard .abs.on{background:rgba(48,209,88,.18);border-color:rgba(48,209,88,.45);color:var(--done)}
.pcard .abs.off{color:var(--text-2)}

/* table */
.tbl-wrap{overflow-x:auto;border:1px solid var(--border);border-radius:var(--r-md)}
table{width:100%;border-collapse:collapse;font-size:.84rem;min-width:720px}
th{font-size:.68rem;text-transform:uppercase;letter-spacing:.08em;color:var(--text-3);text-align:left;padding:10px 12px;background:rgba(0,0,0,.3);border-bottom:1px solid var(--border)}
td{padding:11px 12px;border-bottom:1px solid var(--border);vertical-align:top}
tr:last-child td{border-bottom:none}
td .exname{font-weight:650}
td .note{font-size:.72rem;color:var(--text-3);max-width:260px}
.subbed{color:var(--warn);font-weight:700}
.orig{color:var(--text-3);text-decoration:line-through;font-size:.74rem}

/* rest bar */
.restbar{border:1px solid rgba(255,214,10,.4);background:rgba(255,214,10,.08);border-radius:var(--r-md);padding:14px;display:flex;align-items:center;gap:14px;flex-wrap:wrap}
.restbar.done{border-color:rgba(48,209,88,.6);background:rgba(48,209,88,.12);animation:pulse 1s ease infinite}
@keyframes pulse{0%,100%{box-shadow:0 0 0 0 rgba(48,209,88,.3)}50%{box-shadow:0 0 0 10px rgba(48,209,88,0)}}
.bar{height:6px;border-radius:99px;background:rgba(255,255,255,.1);overflow:hidden;flex:1;min-width:120px}
.bar i{display:block;height:100%;background:var(--warn);border-radius:99px;transition:width .9s linear}
.restbar.done .bar i{background:var(--done)}

/* ladder */
.ladder{display:flex;flex-direction:column;gap:8px}
.lvl{display:flex;align-items:center;gap:12px;padding:11px 14px;border-radius:var(--r-md);border:1px solid var(--border);background:var(--surface-2);cursor:pointer;transition:all .14s}
.lvl:hover{border-color:var(--border-2)}
.lvl .n{width:30px;height:30px;border-radius:10px;display:grid;place-items:center;font-weight:800;font-size:.8rem;background:var(--pill-bg);border:1px solid var(--border-2);flex:none}
.lvl.done{border-color:rgba(48,209,88,.4);background:rgba(48,209,88,.08)}
.lvl.done .n{background:rgba(48,209,88,.2);border-color:rgba(48,209,88,.5);color:var(--done)}
.lvl.current{border-color:rgba(10,132,255,.5);box-shadow:0 0 0 1px rgba(10,132,255,.4)}
.suds{margin-left:auto;font-size:.72rem;font-weight:700;color:var(--text-3)}

/* timeline */
.tl{display:flex;flex-direction:column;gap:6px}
.tl-item{display:grid;grid-template-columns:108px 1fr auto;gap:12px;align-items:center;padding:10px 14px;border-radius:var(--r-md);border:1px solid var(--border);background:var(--surface-2)}
.tl-item .tm{font-size:.78rem;color:var(--text-2)}
.tl-item.now{border-color:rgba(10,132,255,.55);background:rgba(10,132,255,.1);box-shadow:0 0 0 1px rgba(10,132,255,.4)}
