function getAlternatives(ex){
  const out=[];const seen=new Set([ex.name]);
  (ex.subs||[]).forEach(n=>{if(!seen.has(n)){seen.add(n);out.push({name:n,reason:'Programa fuente',tone:'blue',note:'Sustituto oficial prescrito en el PDF del programa.'})}});
  (PLAN_SUBS[ex.name]||[]).forEach(n=>{if(!seen.has(n)){seen.add(n);out.push({name:n,reason:'plan_fitness.md',tone:'green',note:'Sustituto aprobado por salud biomecánica.'})}});
  const cat=(EX_DB[ex.name]||{}).c;
  if(cat){for(const[n,d]of Object.entries(EX_DB)){if(out.length>=6)break;if(!seen.has(n)&&d.c===cat){seen.add(n);out.push({name:n,reason:'FitApp compatible',tone:'gray',note:'Compatible por categoría ('+cat+').'})}}}
  return out;
}

