 return `
  <div class="card">
    ${ids.length>1?`<div class="chips" style="margin-bottom:14px">${ids.map(id=>`<button type="button" class="chip ${id===loggerId?'active':''}" data-action="logger-program" data-id="${id}">${esc(getProgram(id).title)}</button>`).join('')}</div>`:''}
