      <div style="flex:1;min-width:200px">
        <strong style="font-size:.92rem">${esc(day.name)}</strong><br>
        <span class="sub" style="font-size:.76rem;color:var(--text-3)">${checks.length}/${day.ex.length} ejercicios completados</span>
