/* ---------- render principal ---------- */
function render(){
 renderShell();
 const railBefore=$('#program-rail')?$('#program-rail').scrollLeft:0;
 const V={now:renderNow,plan:renderPlan,fitness:renderFitness,clinical:renderClinical,career:renderCareer,german:renderGerman,library:renderLibrary};
 $('#view-root').innerHTML=(V[S.view]||renderNow)();
 const railAfter=$('#program-rail');if(railAfter)railAfter.scrollLeft=railBefore;
 renderOverlay();
}
let toastTimer=null;
function toast(msg){S.ui.toast=msg;renderOverlay();clearTimeout(toastTimer);toastTimer=setTimeout(()=>{S.ui.toast=null;renderOverlay()},2600)}
function beep(){try{const ctx=new (window.AudioContext||window.webkitAudioContext)();const o=ctx.createOscillator();const g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=880;g.gain.setValueAtTime(.001,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.2,ctx.currentTime+.02);g.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+.6);o.start();o.stop(ctx.currentTime+.65)}catch(e){}}

/* ---------- eventos ---------- */
document.addEventListener('click',e=>{
 const el=e.target.closest('[data-action]');
 if(!e.target.closest('#more-wrap')&&S.ui.moreOpen){S.ui.moreOpen=false;renderShell()}
 if(!el)return;
 if(el.tagName==='A')e.preventDefault();
 const a=el.dataset.action;
 switch(a){
  case 'go':go(el.dataset.view);break;
  case 'toggle-more':S.ui.moreOpen=!S.ui.moreOpen;renderShell();break;
  case 'sheet-open':S.ui.sheet={type:el.dataset.sheet};renderOverlay();break;
  case 'sheet-close':S.ui.sheet=null;renderOverlay();break;
  case 'energy':S.app.energy=el.dataset.level;save.app();render();break;
  case 'toggle-simple':S.app.simpleMode=!S.app.simpleMode;save.app();if(S.ui.sheet&&S.ui.sheet.type==='mobile')S.ui.sheet=null;render();toast(S.app.simpleMode?'Modo Simple activado · baja estimulación':'Modo Simple desactivado');break;
  case 'focus-start':S.ui.focus={active:true,startedAt:Date.now()};renderOverlay();break;
  case 'focus-exit':S.ui.focus.active=false;renderOverlay();toast('Bloque cerrado. Registra el avance en la descarga.');break;
  case 'defer-task':{const d=new Date(Date.now()+30*60000);S.now.deferUntil=pad(d.getHours())+':'+pad(d.getMinutes());save.now();render();toast('Tarea aplazada sin culpa.');break}
  case 'toggle-next':{const id=el.dataset.id;S.now.doneTasks=S.now.doneTasks.includes(id)?S.now.doneTasks.filter(x=>x!==id):[...S.now.doneTasks,id];save.now();render();break}
  case 'fit-tab':S.ui.fitTab=el.dataset.tab;render();break;
  case 'logger-program':S.ui.loggerProgramId=el.dataset.id;render();break;
  case 'week-prev':{const p=getProgram(S.ui.fitTab==='tracker'?(S.fit.activeProgramIds.includes(S.ui.loggerProgramId)?S.ui.loggerProgramId:S.fit.activeProgramIds[0]):S.fit.programId);S.fit.currentWeek=Math.max(1,S.fit.currentWeek-1);save.fit();render();break}
  case 'week-next':{const p2=getProgram(S.fit.programId);S.fit.currentWeek=Math.min(p2.weeks.length,S.fit.currentWeek+1);save.fit();render();break}
  case 'week-jump':S.fit.currentWeek=Number(el.dataset.n);save.fit();render();break;
  case 'day-select':S.fit.currentDayId=el.dataset.id;save.fit();render();break;
  case 'session-start':S.ui.session={running:true,startedAt:Date.now()};render();toast('Sesión iniciada. Volumen y tiempo corriendo.');break;
  case 'session-end':S.ui.sheet={type:'end'};renderOverlay();break;
