  case 'session-end':S.ui.sheet={type:'end'};renderOverlay();break;
  case 'end-energy':S.ui.endEnergy=el.dataset.level;renderOverlay();break;
  case 'session-save':{const ids=S.fit.activeProgramIds.length?S.fit.activeProgramIds:[S.fit.programId];const lid=ids.includes(S.ui.loggerProgramId)?S.ui.loggerProgramId:ids[0];const p=getProgram(lid);const dd=activeDay(p,S.fit.currentWeek,S.fit.currentDayId);const secs=S.ui.session.running?Math.floor((Date.now()-S.ui.session.startedAt)/1000):0;S.fit.history.push({id:Date.now(),date:todayISO(),program:p.title,day:dd.day.name,seconds:secs,energy:S.ui.endEnergy});S.app.energy=S.ui.endEnergy;S.ui.session={running:false,startedAt:0};S.fit.sessionChecks[dd.day.id]=[];S.ui.sheet=null;save.fit();save.app();render();toast('Sesión guardada · energía '+ENERGY[S.ui.endEnergy]);break}
  case 'check-ex':{const pp=getProgram(S.fit.activeProgramIds.includes(S.ui.loggerProgramId)?S.ui.loggerProgramId:(S.fit.activeProgramIds[0]||S.fit.programId));const dd2=activeDay(pp,S.fit.currentWeek,S.fit.currentDayId);const arr=S.fit.sessionChecks[dd2.day.id]||[];S.fit.sessionChecks[dd2.day.id]=arr.includes(el.dataset.id)?arr.filter(x=>x!==el.dataset.id):[...arr,el.dataset.id];save.fit();render();break}
  case 'rest-preset':{const s=Number(el.dataset.sec);S.ui.rest={running:true,remaining:s,total:s,done:false};render();break}
