  case 'sub-open':{const p=getProgram(S.fit.programId);const dd3=activeDay(p,S.fit.currentWeek,S.fit.currentDayId);const ex=dd3.day.ex.find(x=>x.id===el.dataset.pid);S.ui.sheet={type:'sub',ex:ex};renderOverlay();break}
