 if(q){res=res.map(function(d){var s=0;q.split(/\s+/).forEach(function(w){if(!w)return;if(d.t.toLowerCase().indexOf(w)>=0)s+=3;if(d.kw.some(function(k){return k.indexOf(w)>=0}))s+=2;if(d.sum.toLowerCase().indexOf(w)>=0)s+=1});return{d:d,s:s}}).filter(function(x){return x.s>0}).sort(function(a,b){return b.s-a.s}).map(function(x){return x.d})}
 return res.length?res.map(function(d){return '<div class="row" style="cursor:default;align-items:flex-start">'+
    '<span class="grow"><span class="t">'+esc(d.t)+'</span><br><span class="m">'+esc(d.sum)+'</span><br><span class="m" style="color:var(--text-3)">Fuente: '+esc(d.src)+'</span></span>'+
