/* ---------- render principal ---------- */
function render(){
 renderShell();
 var railBefore=$('#program-rail')?$('#program-rail').scrollLeft:0;
 var V={now:renderNow,plan:renderPlan,fitness:renderFitness,clinical:renderClinical,career:renderCareer,german:renderGerman,library:renderLibrary};
 $('#view-root').innerHTML=(V[S.view]||renderNow)();
 var railAfter=$('#program-rail');if(railAfter)railAfter.scrollLeft=railBefore;
 renderOverlay();
}
var toastTimer=null;
function toast(msg){S.ui.toast=msg;renderOverlay();clearTimeout(toastTimer);toastTimer=setTimeout(function(){S.ui.toast=null;renderOverlay()},2600)}
function beep(){try{var ctx=new (window.AudioContext||window.webkitAudioContext)();var o=ctx.createOscillator();var g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=880;g.gain.setValueAtTime(.001,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.2,ctx.currentTime+.02);g.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+.6);o.start();o.stop(ctx.currentTime+.65)}catch(e){}}

/* ---------- eventos ---------- */
document.addEventListener('click',function(e){
 var el=e.target.closest?e.target.closest('[data-action]'):null;
 if(!(e.target.closest&&e.target.closest('#more-wrap'))&&S.ui.moreOpen){S.ui.moreOpen=false;renderShell()}
 if(!el)return;
 if(el.tagName==='A')e.preventDefault();
 var a=el.getAttribute('data-action');
 switch(a){
  case 'go':go(el.getAttribute('data-view'));break;
  case 'toggle-more':S.ui.moreOpen=!S.ui.moreOpen;renderShell();break;
  case 'sheet-open':S.ui.sheet={type:el.getAttribute('data-sheet')};renderOverlay();break;
  case 'sheet-close':S.ui.sheet=null;renderOverlay();break;
  case 'energy':S.app.energy=el.getAttribute('data-level');save.app();render();break;
  case 'toggle-simple':S.app.simpleMode=!S.app.simpleMode;save.app();if(S.ui.sheet&&S.ui.sheet.type==='mobile')S.ui.sheet=null;render();toast(S.app.simpleMode?'Modo Simple activado · baja estimulación':'Modo Simple desactivado');break;
  case 'focus-start':S.ui.focus={active:true,startedAt:Date.now()};renderOverlay();break;
  case 'focus-exit':S.ui.focus.active=false;renderOverlay();toast('Bloque cerrado. Registra el avance en la descarga.');break;
  case 'defer-task':{var dd=new Date(Date.now()+30*60000);S.now.deferUntil=pad(dd.getHours())+':'+pad(dd.getMinutes());save.now();render();toast('Tarea aplazada sin culpa.');break}
  case 'toggle-next':{var id=el.getAttribute('data-id');S.now.doneTasks=S.now.doneTasks.indexOf(id)>=0?S.now.doneTasks.filter(function(x){return x!==id}):S.now.doneTasks.concat([id]);save.now();render();break}
  case 'fit-tab':S.ui.fitTab=el.getAttribute('data-tab');render();break;
  case 'logger-program':S.ui.loggerProgramId=el.getAttribute('data-id');render();break;
  case 'week-prev':S.fit.currentWeek=Math.max(1,S.fit.currentWeek-1);save.fit();render();break;
  case 'week-next':{var pw=getProgram(loggerProgramId()).weeks.length;S.fit.currentWeek=Math.min(pw,S.fit.currentWeek+1);save.fit();render();break}
  case 'week-jump':S.fit.currentWeek=Number(el.getAttribute('data-n'));save.fit();render();break;
  case 'day-select':S.fit.currentDayId=el.getAttribute('data-id');save.fit();render();break;
  case 'session-start':S.ui.session={running:true,startedAt:Date.now()};render();toast('Sesión iniciada. Tiempo corriendo.');break;
  case 'session-end':S.ui.sheet={type:'end'};renderOverlay();break;
  case 'end-energy':S.ui.endEnergy=el.getAttribute('data-level');renderOverlay();break;
  case 'session-save':{var lid=loggerProgramId();var p=getProgram(lid);var ad=activeDay(p,S.fit.currentWeek,S.fit.currentDayId);var secs=S.ui.session.running?Math.floor((Date.now()-S.ui.session.startedAt)/1000):0;S.fit.history.push({id:Date.now(),date:todayISO(),program:p.title,day:ad.day.name,seconds:secs,energy:S.ui.endEnergy});S.app.energy=S.ui.endEnergy;S.ui.session={running:false,startedAt:0};S.fit.sessionChecks[ad.day.id]=[];S.ui.sheet=null;save.fit();save.app();render();toast('Sesión guardada · energía '+ENERGY[S.ui.endEnergy]);break}
  case 'check-ex':{var cp=getProgram(loggerProgramId());var cad=activeDay(cp,S.fit.currentWeek,S.fit.currentDayId);var arr=S.fit.sessionChecks[cad.day.id]||[];var cid=el.getAttribute('data-id');S.fit.sessionChecks[cad.day.id]=arr.indexOf(cid)>=0?arr.filter(function(x){return x!==cid}):arr.concat([cid]);save.fit();render();break}
  case 'rest-preset':{var rs=Number(el.getAttribute('data-sec'));S.ui.rest={running:true,remaining:rs,total:rs,done:false};render();break}
  case 'rest-cancel':S.ui.rest={running:false,remaining:0,total:0,done:false};render();break;
  case 'program-inspect':S.fit.programId=el.getAttribute('data-id');save.fit();render();break;
  case 'program-toggle':{var pid=el.getAttribute('data-id');var act=S.fit.activeProgramIds;if(act.indexOf(pid)>=0){if(act.length>1)S.fit.activeProgramIds=act.filter(function(x){return x!==pid});else toast('Debe quedar al menos un programa activo.');}else{S.fit.activeProgramIds=act.concat([pid]);toast(getProgram(pid).title+' activado en el Tracker Hoy.');}if(S.fit.activeProgramIds.indexOf(S.fit.programId)<0)S.fit.programId=S.fit.activeProgramIds[0];save.fit();render();break}
  case 'sub-open':{var sp=getProgram(S.fit.programId);var sad=activeDay(sp,S.fit.currentWeek,S.fit.currentDayId);var sex=sad.day.ex.find(function(x){return x.id===el.getAttribute('data-pid')});if(sex){S.ui.sheet={type:'sub',ex:sex};renderOverlay();}break}
  case 'sub-pick':{var alt=S.ui.subList[Number(el.getAttribute('data-idx'))];if(alt&&S.ui.sheet&&S.ui.sheet.ex){S.fit.overrides[S.ui.sheet.ex.id]=alt.name;save.fit();toast('Sustituido: '+alt.name);}S.ui.sheet=null;render();break}
  case 'sub-revert':{delete S.fit.overrides[el.getAttribute('data-pid')];save.fit();render();toast('Ejercicio original restaurado.');break}
  case 'skills-tab':S.ui.skillsTab=el.getAttribute('data-tab');render();break;
  case 'skills-filter':S.ui.skillsFilter=!S.ui.skillsFilter;render();break;
  case 'skill-toggle':{var sid=el.getAttribute('data-id');if(S.skills.completed.indexOf(sid)>=0)break;if(S.skills.active.indexOf(sid)>=0){S.skills.active=S.skills.active.filter(function(x){return x!==sid});S.skills.completed=S.skills.completed.concat([sid]);toast('Paso completado 🎉');}else{S.skills.active=S.skills.active.concat([sid]);toast('Habilidad activada en Mi Práctica.');}save.skills();render();break}
  case 'skill-deactivate':S.skills.active=S.skills.active.filter(function(x){return x!==el.getAttribute('data-id')});save.skills();render();toast('Habilidad desactivada.');break;
  case 'practice-step':{var psid=el.getAttribute('data-id');S.skills.completed=S.skills.completed.indexOf(psid)>=0?S.skills.completed.filter(function(x){return x!==psid}):S.skills.completed.concat([psid]);save.skills();render();break}
  case 'clin-tab':S.clin.tab=el.getAttribute('data-tab');render();break;
  case 'adhd-check':{var aid=el.getAttribute('data-id');S.clin.adhdChecks=S.clin.adhdChecks.indexOf(aid)>=0?S.clin.adhdChecks.filter(function(x){return x!==aid}):S.clin.adhdChecks.concat([aid]);save.clin();render();break}
  case 'adhd-reset':S.clin.adhdChecks=[];save.clin();render();toast('Checklist del día reiniciada.');break;
  case 'ladder-toggle':{var lv=Number(el.getAttribute('data-lvl'));S.clin.ladderDone=S.clin.ladderDone.indexOf(lv)>=0?S.clin.ladderDone.filter(function(x){return x!==lv}):S.clin.ladderDone.concat([lv]);save.clin();render();break}
  case 'cannabis-tonight':{if(S.clin.lastCannabisFree===todayISO()){S.clin.lastCannabisFree=null;S.clin.cannabisStreak=Math.max(0,S.clin.cannabisStreak-1);}else{var y=new Date(Date.now()-864e5).toISOString().slice(0,10);S.clin.cannabisStreak=S.clin.lastCannabisFree===y?S.clin.cannabisStreak+1:1;S.clin.lastCannabisFree=todayISO();toast('Noche sin cannabis registrada · racha '+S.clin.cannabisStreak);}save.clin();render();break}
  case 'reg-apply':{var rid=el.getAttribute('data-id');S.clin.regLog[rid]=(S.clin.regLog[rid]||0)+1;save.clin();render();toast('Estrategia aplicada. Pausa de recuperación activa.');break}
  case 'phase-select':S.career.phase=Number(el.getAttribute('data-id'));save.career();render();break;
  case 'phase-check':{var pcid=el.getAttribute('data-id');S.career.checks=S.career.checks.indexOf(pcid)>=0?S.career.checks.filter(function(x){return x!==pcid}):S.career.checks.concat([pcid]);save.career();render();break}
  case 'actions-inc':S.career.actions++;save.career();render();if(S.career.actions===30)toast('Cadencia mínima semanal alcanzada (30).');break;
  case 'actions-dec':S.career.actions=Math.max(0,S.career.actions-1);save.career();render();break;
  case 'german-mark':{var gt=todayISO();if(S.german.lastDate===gt){toast('La sesión de hoy ya está registrada ✓');break}var gy=new Date(Date.now()-864e5).toISOString().slice(0,10);S.german.streak=S.german.lastDate===gy?S.german.streak+1:1;S.german.lastDate=gt;save.german();render();toast('🔥 Racha '+S.german.streak+' días');break}
  case 'german-check':{var g2=todayISO();var gitems=S.german.checks.date===g2?S.german.checks.items:[];var gid=el.getAttribute('data-id');gitems=gitems.indexOf(gid)>=0?gitems.filter(function(x){return x!==gid}):gitems.concat([gid]);S.german.checks={date:g2,items:gitems};save.german();render();break}
  case 'lib-filter':S.ui.libFilter=el.getAttribute('data-domain');render();break;
  case 'rescue-start':S.ui.rescue={running:true,remaining:600};renderOverlay();break;
  case 'rescue-stop':S.ui.rescue={running:false,remaining:0};renderOverlay();toast('Rescate completado. Decide con libertad: parar o seguir.');break;
 }
});
