function go(view){S.view=view;S.ui.moreOpen=false;S.ui.sheet=null;const h='#/'+view;if(location.hash!==h)history.replaceState(null,'',h);render();window.scrollTo({top:0})}
function viewFromHash(){const h=location.hash.replace('#/','');return VIEWS.some(v=>v.id===h)?h:'now'}

/* ---------- helpers de dominio ---------- */
function currentBlock(){const n=new Date();const m=n.getHours()*60+n.getMinutes();return SCHEDULE.find(b=>m>=toMin(b.s)&&m<toMin(b.e))||null}
function activeDay(program,week,dayId){const w=program.weeks[Math.min(Math.max(week-1,0),program.weeks.length-1)]||program.weeks[0];return{week:w,day:w.days.find(d=>d.id===dayId)||w.days[0]}}
function dispName(ex){return S.fit.overrides[ex.id]||ex.name}

