  case 'skills-tab':S.ui.skillsTab=el.getAttribute('data-tab');render();break;
  case 'skills-filter':S.ui.skillsFilter=!S.ui.skillsFilter;render();break;
  case 'skill-toggle':{var sid=el.getAttribute('data-id');if(S.skills.completed.indexOf(sid)>=0)break;if(S.skills.active.indexOf(sid)>=0){S.skills.active=S.skills.active.filter(function(x){return x!==sid});S.skills.completed=S.skills.completed.concat([sid]);toast('Paso completado 🎉');}else{S.skills.active=S.skills.active.concat([sid]);toast('Habilidad activada en Mi Práctica.');}save.skills();render();break}
  case 'skill-deactivate':S.skills.active=S.skills.active.filter(function(x){return x!==el.getAttribute('data-id')});save.skills();render();toast('Habilidad desactivada.');break;
  case 'practice-step':{var psid=el.getAttribute('data-id');S.skills.completed=S.skills.completed.indexOf(psid)>=0?S.skills.completed.filter(function(x){return x!==psid}):S.skills.completed.concat([psid]);save.skills();render();break}
  case 'clin-tab':S.clin.tab=el.getAttribute('data-tab');render();break;
  case 'adhd-check':{var aid=el.getAttribute('data-id');S.clin.adhdChecks=S.clin.adhdChecks.indexOf(aid)>=0?S.clin.adhdChecks.filter(function(x){return x!==aid}):S.clin.adhdChecks.concat([aid]);save.clin();render();break}
  case 'adhd-reset':S.clin.adhdChecks=[];save.clin();render();toast('Checklist del día reiniciada.');break;
  case 'ladder-toggle':{var lv=Number(el.getAttribute('data-lvl'));S.clin.ladderDone=S.clin.ladderDone.indexOf(lv)>=0?S.clin.ladderDone.filter(function(x){return x!==lv}):S.clin.ladderDone.concat([lv]);save.clin();render();break}
  case 'cannabis-tonight':{if(S.clin.lastCannabisFree===todayISO()){S.clin.lastCannabisFree=null;S.clin.cannabisStreak=Math.max(0,S.clin.cannabisStreak-1);}else{var y=new Date(Date.now()-864e5).toISOString().slice(0,10);S.clin.cannabisStreak=S.clin.lastCannabisFree===y?S.clin.cannabisStreak+1:1;S.clin.lastCannabisFree=todayISO();toast('Noche sin cannabis registrada · racha '+S.clin.cannabisStreak);}save.clin();render();break}
